const membres = document.querySelectorAll("#groupe .membre");
for (const membre of membres) { membre.textContent = "Membre : " + membre.dataset.nom; }
document.querySelector("#bilan").textContent = membres.length === 0 ? "Aucun membre" : membres.length + " membres";

