const ateliers = document.querySelectorAll("#ateliers .atelier");
let ouverts = 0;
for (const atelier of ateliers) { if (atelier.dataset.ouvert === "oui") { ouverts = ouverts + 1; } }
document.querySelector("#bilan").textContent = ateliers.length === 0 ? "Aucun atelier" : ouverts + " ouverts / " + ateliers.length + " ateliers";

